-- Align advertised schemas with the real database limits and atomic approval policy.
update public.operator_tool set approval_required=true where name in ('post.create','post.publish','post.delete','post.edit','poll.create','notification.send','moderation.remove_content','moderation.suspend','moderation.ban','moderation.restore','campaign.schedule');
update public.operator_tool set input_schema='{"type":"object","properties":{"post_id":{"type":"string","format":"uuid"},"question":{"type":"string","minLength":1,"maxLength":240},"options":{"type":"array","minItems":2,"maxItems":4,"items":{"type":"string","minLength":1,"maxLength":80}}},"required":["post_id","options"],"additionalProperties":false}'::jsonb where name='poll.create';
update public.operator_tool set input_schema='{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":120},"body":{"type":"string","minLength":1,"maxLength":500},"audience":{"type":"string","enum":["all","world","followers"]},"world":{"type":"string","enum":["kdrama","cdrama","anime","hollywood"]}},"required":["title","body","audience"],"additionalProperties":false}'::jsonb where name='notification.send';
update public.operator_tool set input_schema=jsonb_set(input_schema,'{properties,name}','{"type":"string","minLength":1,"maxLength":120}'::jsonb) where name='campaign.create';
